  function conversation(){return state.conversation||(state.conversation={asked:new Set(),intros:new Set(),short:false,simple:false,noBudget:false,noQuestions:false,language:null,beginner:false});}
  function policyUncertainty(s){if(/backup|restore|نسخ احتياط|استعاد/.test(s))return t('The backup schedule, retention and restore terms for that plan need confirmation. I cannot promise a backup or recovery service without verified terms.','جدول النسخ الاحتياطي والاحتفاظ بالنسخ وشروط الاستعادة للباقة محتاجين تأكيد. مش هأكد خدمة نسخ أو استعادة من غير شروط موثقة.');if(/tax|vat|ضريب|ضرائب/.test(s))return t('The applicable taxes and final checkout total need confirmation. I cannot provide an unverified tax rate.','الضرائب المطبقة والإجمالي النهائي محتاجين تأكيد. مش هذكر نسبة ضريبة غير موثقة.');return t('That specific policy or plan limit is not verified in the available information. The team needs to confirm it before you rely on it.','السياسة أو حد الباقة اللي بتسأل عنه مش موثق في المعلومات المتاحة. لازم الفريق يأكده قبل ما تعتمد عليه.');}
