   if(/(?:don't|do not|rather not|won't) (?:want to )?(?:answer|share|say|tell|disclose)|مش عايز (?:اجاوب|اقول)|مش حابب.*اجاوب/.test(s)&&!(/budget|ميزاني/.test(s))&&(state.consultExpect||state.flow.expect)){const field=state.consultExpect||state.flow.expect;state.consultUnknown=state.consultUnknown||{};state.consultUnknown[field]=true;state.unknownFields[field]=true;state.consultExpect=null;state.flow.expect=null;return response('preference',t('That is fine. We can leave that detail open and work with the requirements you have shared.','تمام، ينفع نسيب المعلومة دي من غير إجابة ونكمل بالاحتياجات اللي ذكرتها.'));}
   if(/keep (?:it|your (?:answer|answers|reply|replies)) short|brief(?:ly)? please|short answers?|اختصر|رد(?:ود)? مختصر/.test(s)){c.short=true;changed=true;}
   if(/explain (?:it )?simply|like i'?m a beginner|don't understand technical terms|مش فاهم.*مصطلح|ببساطه|ببساطة/.test(s)){c.simple=true;changed=true;}
   if(/(?:don't|do not|stop|never) ask.*budget|(?:don't|do not|won't|rather not) (?:want to )?(?:share|say|disclose).*budget|مش عايز.*(?:ميزاني|الميزانيه)|متسالش.*ميزاني/.test(s)){c.noBudget=true;state.unknownFields.budget=true;if(state.flow.expect?.startsWith('budget'))state.flow.expect=null;changed=true;}
   if(/just answer(?: my question)?|no (?:more )?questions|don't ask.*questions|جاوب.*بس|من غير اسيله|متسالنيش/.test(s)){c.noQuestions=true;changed=true;}
   const language=L.instruction(original)||(/كلمني (?:بالعربي|عربي)|اتكلم عربي/.test(s)?'ar':null);
   if(language){c.language=language==='auto'?null:language;state.languagePreference=c.language;state.language=c.language||L.detect(original,state.language);changed=true;}
   const direct=/recommend|help.*choose|ساعدني.*اختار|رشح|what(?:'s| is| are| does)|how (?:much|does|do)|explain (?:web )?hosting|\b(?:dns|nameservers?|ssl|renewal|domain|shared|cloud|reseller|wordpress)\b|يعني.*استضاف|اشرح.*استضاف|بكام|الدومين|السحابيه|المشتركه/.test(s);
   if(changed&&!direct&&!/\b(?:i have|i need|my (?:site|website)|price|cost|compare|shared hosting|cloud hosting)\b|عندي|موقعي|بكام|قارن/.test(s))return response('preference',c.noBudget?t('That is fine. We can compare relevant hosting options using your website requirements instead.','تمام، مش لازم تقول الميزانية. نقدر نقارن الاختيارات حسب احتياجات موقعك.'):c.noQuestions?t('Of course. I will answer directly without starting a questionnaire.','أكيد، هجاوب مباشرة من غير أسئلة إضافية.'):language?t('I will continue in English. Your project details are unchanged.','تمام، هكمل معاك بالعربي. تفاصيل مشروعك زي ما هي.'):t('Of course. I will keep the explanation '+(c.short?'short':'simple')+'.','أكيد، هخلي الشرح '+(c.short?'مختصر':'بسيط')+'.'));
   if(/explain hosting.*beginner|(?:what is|explain) (?:web )?hosting[?.!]*$|(?:مش فاهم|مش عارف).*يعني.*استضاف/.test(s))return response('definition',t('Hosting is where your website and its files run so people can open it online. A domain is the address people enter in their browser—like a shop address and the premises it points to.','الاستضافة هي المكان اللي بيتخزن عليه موقعك وملفاته علشان الناس تقدر تفتحه على الإنترنت. والدومين هو عنوان الموقع اللي بيكتبوه في المتصفح؛ زي عنوان المحل والمكان نفسه.'));
