   if((c.short||c.simple)&&['categoryEducation','compare'].includes(r.intent)){
    const ids=categoryEducationRequest(s)||selected(s).map(p=>p.id),rows=kb.foundation?.hosting_categories||[];
    const meanings=ids.map(id=>rows.find(x=>x.value?.id===id)?.meaning?.value?.[state.language]).filter(Boolean);
    if(meanings.length)r.text=meanings.join('\n')+'\n'+t('Actual limits and suitability depend on the verified plan specifications.','الحدود والملاءمة حسب مواصفات الباقة الموثقة.');
   }
   if(c.noQuestions&&!['privacy','validation','confirmation'].includes(r.intent)){
    r.text=r.text.replace(/[^.!?؟\n]*[?؟]/g,'').trim()||t('A confirmed plan choice depends on the website requirements and verified plan limits. You can review the published features without sharing more details.','تأكيد اختيار الباقة حسب احتياجات الموقع وحدود الباقة الموثقة. تقدر تراجع المميزات المنشورة من غير مشاركة تفاصيل إضافية.');
    state.consultExpect=null;state.flow.expect=null;
   }
   const domain=r.intent==='domain'||!!state.domainContext&&/domain|dns|دومين|نطاق/.test(s),support=r.intent==='support'||r.intent==='human',direct=['definition','categoryEducation','planPricing','pricing','company','preference'].includes(r.intent);
   if(!r.quick.length&&!['privacy','validation','preference','confirmation'].includes(r.intent))r.quick=L.quick(domain?['basics']:support?['human']:direct?[]:['profile'],state.language);
   const onlyShared=state.profile.requestedCategory?.value==='shared';
   const seen=new Set();r.quick=r.quick.filter(q=>{if(seen.has(q.id))return false;seen.add(q.id);if((domain||support)&&['choose','compare','resume','company','wordpress','store','budget'].includes(q.id))return false;if(c.noQuestions&&['choose','resume','unknown','budgetLow','budgetMid','budgetHigh','oneSite','fewSites','manySites'].includes(q.id))return false;if(c.noBudget&&/^budget/.test(q.id))return false;if(onlyShared&&['compare','wordpress','cloud','reseller'].includes(q.id))return false;if(state.whatsappDeclined&&['human','summary'].includes(q.id))return false;return true;});
