   if(/(?:don't|do not) assume.*vps/.test(s)&&v('technicalReview'))return reply('advice','Agreed. VPS availability is not verified. Your application needs a technical compatibility review against approved services; no product or capacity is assumed.','تمام. توافر VPS مش مؤكد. تطبيقك محتاج مراجعة توافق فني مع الخدمات المعتمدة؛ مش هفترض منتج أو سعة.');
   if(/easy to manage|easy management|سهل.*ادار/.test(s)&&v('platform')){ex.facts.priorities={value:['easy_management'],certainty:'explicit',source:'customer message'};return reply('consultation','I have recorded easy management as a priority. Platform compatibility and actual plan limits still need verification.','سجلت سهولة الإدارة كأولوية. توافق المنصة وحدود الباقة الفعلية لسه محتاجين تأكيد.');}
   if(v('website')==='online_store'&&/don't know|do not know|not sure|مش عارف/.test(s)&&/at once|concurr|checkout|check out|متزامن/.test(s)){(state.consultUnknown||={}).concurrentUsers=true;return reply('consultation','That is fine; concurrent checkout demand remains unknown. It needs review before confirming store capacity, rather than assuming a visitor count proves a plan fits.','عادي؛ حجم عمليات الدفع المتزامنة لسه مش معروف. محتاج مراجعة قبل تأكيد سعة المتجر، بدل افتراض إن عدد الزيارات يثبت ملاءمة الباقة.');}
